const routeMap = new Map(CACHED_ROUTE_SUBSET.map(route => [`${route.from}:${route.to}`, route]));

function toRoute(route, selected, reversed = false) {
  const variant = selected === route.alternative ? 'alternative' : 'primary';
  return {
    id: `cached-${route.from}-${route.to}-${variant}${reversed ? '-reversed' : ''}`,
    from: reversed ? route.to : route.from,
    to: reversed ? route.from : route.to,
    variant,
    coordinates: reversed ? [...selected.coordinates].reverse() : selected.coordinates,
    distanceMeters: selected.distanceMeters,
    durationSeconds: selected.durationSeconds,
    source: reversed ? 'cached-subset-reversed' : 'cached-subset',
  };
}

export function getCachedRouteOptions(fromId, toId) {
  return routeMap.get(`${fromId}:${toId}`) || routeMap.get(`${toId}:${fromId}`) || null;
}

export function getCachedRoute(fromId, toId, variant = 'primary') {
  const exact = routeMap.get(`${fromId}:${toId}`);
  const reverse = !exact ? routeMap.get(`${toId}:${fromId}`) : null;
  const route = exact || reverse;
  if (!route) return null;
  const selected = variant === 'alternative' && route.alternative ? route.alternative : route.primary;
  return toRoute(route, selected, Boolean(reverse));
}

export function getRouteVariantSummary(fromId, toId) {
  const exact = routeMap.get(`${fromId}:${toId}`);
  const reverse = !exact ? routeMap.get(`${toId}:${fromId}`) : null;
  const route = exact || reverse;
  if (!route) return null;
  return {
    from: fromId,
    to: toId,
    reversed: Boolean(reverse),
    primary: {
      distanceMeters: route.primary.distanceMeters,
      durationSeconds: route.primary.durationSeconds,
    },
    alternative: route.alternative ? {
      distanceMeters: route.alternative.distanceMeters,
      durationSeconds: route.alternative.durationSeconds,
    } : null,
  };
}
